def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    recent = history[-10:] if n >= 10 else history
    recent_len = len(recent)
    recent_opp_c = sum(1 for _, o in recent if o == 'C')
    recent_opp_d = recent_len - recent_opp_c
    recent_rate = recent_opp_c / recent_len

    full_opp_c = sum(1 for _, o in history if o == 'C')
    full_rate = full_opp_c / n

    my_c = sum(1 for m, _ in history if m == 'C')
    my_d = n - my_c

    my_last, opp_last = history[-1]

    if full_opp_c == 0:
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D' and recent_opp_d <= 1 and recent_rate >= 0.7:
                return 'C'
            return 'D'

        if recent_rate >= 0.65 and recent_opp_d <= 2 and full_rate >= 0.55:
            return 'C'
        return 'D'

    if my_last == 'D':
        if my_d == 1 and recent_opp_d == 0:
            return 'C'

        if recent_opp_d == 0 and full_rate >= 0.6:
            return 'D'

        if recent_rate >= 0.55 and full_rate >= 0.5:
            return 'C'

        return 'D'

    if my_d == 0 and n >= 4 and recent_opp_d == 0 and full_opp_c == n:
        return 'D'

    if recent_opp_d == 0 and n >= 2:
        if history[-2][0] == 'D' and history[-1][0] == 'C':
            return 'D'

    if recent_rate < 0.5:
        return 'D'

    return 'C'
